listitem.para:
the machine is a dedicated firewall or router,
and you want the entire policy in one file you can read top to
bottom, comment, diff, and keep in version control;

almost any computer made this century — an old desktop, a small
ARM board like a Raspberry Pi, a little fanless x86 box, or a virtual
machine;

sect2.programlisting:
#!/usr/sbin/nft -f
#
# Two-interface firewall: eth0 = Internet, eth1 = LAN (192.168.1.0/24)

flush ruleset

define WAN = eth0
define LAN = eth1
define LANNET = 192.168.1.0/24

table inet filter {
    chain input {
        type filter hook input priority 0; policy drop;

        # accept anything from ourselves and from established sessions
        iif lo accept
        ct state established,related accept
        ct state invalid drop

        # ICMP/ICMPv6 - don't break ping and path-MTU discovery
        ip protocol icmp accept
        meta l4proto ipv6-icmp accept

        # services the LAN may ask the firewall itself for
        iifname $LAN tcp dport ssh accept
        iifname $LAN udp dport { domain, bootps } accept
        iifname $LAN tcp dport domain accept

        # nothing from the Internet side; log the attempts
        iifname $WAN log prefix "fw-input-drop " counter drop
    }

    chain forward {
        type filter hook forward priority 0; policy drop;

        # LAN out to the world, and the replies back in
        iifname $LAN oifname $WAN accept
        ct state established,related accept

        # port forward: web server on the LAN (see nat table below)
        iifname $WAN oifname $LAN ip daddr 192.168.1.11 \
            tcp dport { http, https } accept

        log prefix "fw-forward-drop " counter drop
    }

    chain output {
        type filter hook output priority 0; policy accept;
    }
}

table ip nat {
    chain prerouting {
        type nat hook prerouting priority -100;

        # publish the internal web server
        iifname $WAN tcp dport { http, https } dnat to 192.168.1.11
    }

    chain postrouting {
        type nat hook postrouting priority 100;

        # masquerade the LAN as it leaves for the Internet
        oifname $WAN ip saddr $LANNET masquerade
    }
}

sect1.programlisting:
table ip proxy {
    chain prerouting {
        type nat hook prerouting priority -110;
        iifname "eth1" tcp dport 80 redirect to :3129
    }
}

appendix.programlisting:
#!/usr/sbin/nft -f
#
# Firewall ruleset - Firewall-HOWTO v2.0
# eth0 = Internet, eth1 = LAN (192.168.1.0/24)
# Web server published at 192.168.1.11

flush ruleset

define WAN = eth0
define LAN = eth1
define LANNET = 192.168.1.0/24

table inet filter {
    chain input {
        type filter hook input priority 0; policy drop;
        iif lo accept
        ct state established,related accept
        ct state invalid drop
        ip protocol icmp accept
        meta l4proto ipv6-icmp accept
        iifname $LAN tcp dport ssh accept
        iifname $LAN udp dport { domain, bootps } accept
        iifname $LAN tcp dport domain accept
        iifname $WAN log prefix "fw-input-drop " counter drop
    }
    chain forward {
        type filter hook forward priority 0; policy drop;
        iifname $LAN oifname $WAN accept
        ct state established,related accept
        iifname $WAN oifname $LAN ip daddr 192.168.1.11 \
            tcp dport { http, https } accept
        log prefix "fw-forward-drop " counter drop
    }
    chain output {
        type filter hook output priority 0; policy accept;
    }
}

table ip nat {
    chain prerouting {
        type nat hook prerouting priority -100;
        iifname $WAN tcp dport { http, https } dnat to 192.168.1.11
    }
    chain postrouting {
        type nat hook postrouting priority 100;
        oifname $WAN ip saddr $LANNET masquerade
    }
}
